algorithm:
{
First, compute the remaining capacity after adding the item to each bin; then assign higher priority to bins where the remaining capacity is non‑negative and as small as possible, while giving zero priority to bins that would overflow.
}

function:
def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_capacity = bins - (bins - item).clip(min=0)
    return remaining_capacity

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    target = 0.06 * item
    return np.where(valid, 1 / (np.abs(remaining - target) + 1), 0.0)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    target_remaining = 0.1 * bins
    return np.where(valid, 1 / (np.abs(remaining - target_remaining) + 1), 0.0)
